# TEAM CALL PLAN (shared byte 7, bits 2-7 only; bits 0-1 stay the lock flags):
# A. A champion that sees enemies within 6 while healthy writes a rolling call code (1..7, changing every 8 rounds).
# B. Allies read the call; a fresh call (this or the previous code) means a fight is on at the caller's side.
# C. Calls are a rally: an uncommitted champion (no gems, no target in reach) walks to the nearest visible ally before camps.
# D. Only the code is shared: no tile is encoded, so the rally follows the ally that is in the fight.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
# team call (this version): rolling call code in shared byte 7 bits 2-7, rally to allies in a fight
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# a fresh team call: stored code equals the current or previous code (codes 1..7, 0 = none)
def call_on():
    return sx >= 1 and (sx == cw or sx == cw - 1 or (cw == 1 and sx == 7))

