# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

# macro-gold: early, a gold cluster within 4 tiles is a cheap detour (no monsters, 20 gold each)
if round_number() < 500 and fuel_remaining() > 60000:
