    dash_to(1, goal)
# VISION: no enemy in sight on a camp walk, so hide the walk behind cover.
# Standing in a bush: ward our own tile. Otherwise: ward an altar within 2 (free, recharges over 10 turns).
# Fuel-gated; the altar ward is only placed when one is actually in range.
if count(foes) == 0 and fuel_remaining() > 50000:
    if contains( bushes(), position() ):
        place_ward( position() )
    elif exists( first( filter( altars(), within(2, position()) ) ) ):
        place_ward( first( filter( altars(), within(2, position()) ) ) )
