# beacon helpers: bit value b (4, 8, 16, 32) of shared byte 7 is set when floor(v/b) is odd
def fbit(b):
    return floor(read_shared(7) / b) - 2 * floor(read_shared(7) / (2 * b)) == 1

def pfight():
    return (i_am(champ_vendetta()) and fbit(8)) or (i_am(champ_vesper_vale()) and fbit(4)) or (i_am(champ_tavi()) and fbit(32)) or (i_am(champ_ryth()) and fbit(16))

def set_beacon(bit, on):
    let v = read_shared(7)
    let cur = floor(v / bit) - 2 * floor(v / (2 * bit))
    if on:
        write_shared(7, v - cur * bit + bit)
    else:
        write_shared(7, v - cur * bit)

