        if ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(ally_low)) <= slot_range(1):
            cast_at_unit(1, ally_low)
    attack(enemy)
    # attack reset: self-cast after the basic attack, then attack again
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
