# OPPORTUNISTIC BANKING: cheap altar nearby -> bank a small bag; enemies around -> bank a 10+ bag early
let aeta = altar_eta()
let bag_ready = (i_am(champ_vesper_vale()) and gems() >= 10) or (not i_am(champ_vesper_vale()) and gems() >= 25) or round_number() > 1500 or health() < 0.3 * max_health() or (gems() >= 8 and aeta <= 3) or (gems() >= 4 and aeta <= 1) or (gems() >= 10 and (lurk > 0 or count(foes) > 0) and aeta <= 6)
