    end_turn()

# tribute with a worthwhile bag (or when hurt / late game); an enemy within 6 makes 10 gems enough
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health() or (gems() >= 10 and enemies_within(6) > 0)
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
