    end_turn()

# CARRY GUARD: a carrier who sees an enemy closing runs the bag to a nearby altar and tributes instead of fighting
if not at_spawn and gems() >= 4 and exists( first(foes) ):
    let threat = threat_eta()
    let guard_role = (i_am(champ_vesper_vale()) and gems() >= 4) or (gems() >= 8 and (gems() >= 15 or not i_am(champ_vendetta()) or local_strength(6) < 1.3))
    if guard_role and threat <= 3:
        let guard_altar = first( minus( filter( altars(), within(1, position()) ), locked_altars() ) )
        if exists(guard_altar):
