# CAST-AHEAD: stun/damage/AoE at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        let ahead_stun_first = slot_stun(0) >= slot_stun(1)
        if ahead_stun_first:
            fight_cast(0, near_foe)
            fight_cast(1, near_foe)
        else:
            fight_cast(1, near_foe)
            fight_cast(0, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # RETREAT: outnumbered or outclassed locally and the target is not nearly dead, so step back and re-engage later
    let fight_local = local_strength(4)
    if fight_local < 0.8 and unit_health_frac(enemy) > 0.3473 and can_move():
        move_away_from( unit_position(enemy) )
        end_turn()
    # stun before burst: the slot with the stun goes first, then the other
    let stun_first = slot_stun(0) >= slot_stun(1)
    if stun_first:
        fight_cast(0, enemy)
        fight_cast(1, enemy)
    else:
        fight_cast(1, enemy)
        fight_cast(0, enemy)
    # ALLY HEAL: a hurt visible ally within heal range gets the heal slot cast on it
    let ally_low = weakest( allies_visible() )
    if exists(ally_low) and unit_health_frac(ally_low) < 0.5:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(ally_low)) <= slot_range(0):
            cast_at_unit(0, ally_low)
        if ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(ally_low)) <= slot_range(1):
            cast_at_unit(1, ally_low)
    attack(enemy)
    # attack reset: self-cast after the basic attack, then attack again
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
