# OPPORTUNISTIC BANKING: cheap altar nearby -> bank a small bag; enemies around -> bank a 10+ bag early; hurt -> bank a 4+ bag within 8 tiles
let aeta = altar_eta()
let bag_ready = (i_am(champ_vesper_vale()) and gems() >= 10) or (not i_am(champ_vesper_vale()) and gems() >= 15) or round_number() > 1500 or health() < 0.3 * max_health() or (gems() >= 6 and aeta <= 4) or (gems() >= 4 and aeta <= 1) or (gems() >= 10 and (lurk > 0 or count(foes) > 0) and aeta <= 6) or (gems() >= 4 and health() < 0.6 * max_health() and aeta <= 8)
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
