# ABILITY PLAN (fight micro, one change): cast order and cast targets in fights.
# 1. Stun-capable slot goes first (stun before burst), so the enemy is held before damage lands.
# 2. An AoE slot is cast at the target's tile (cast_at_tile), so it hits the group around it.
# 3. Shield and heal slots fire on self only when hurt (below 70% health), not on cooldown idle.
# 4. Attack resets are never cast at an enemy (they fail there); they stay self-cast after a basic attack.
# Everything else is v1 (monolith claim commit, vision wards, lock once, cast-ahead, tribute, camp farming).
# ROLES: Vesper Vale is the courier and banks gems at 10 instead of 25, since a dead carrier drops them to its killer.
# COMBAT: when local_strength(4) < 0.8 against a healthy enemy, step away instead of trading blows, then re-engage later.
# version 4 (abilities): in fights, a hurt visible ally within heal range gets the heal slot cast on it (cast_at_unit), not only on self.
# version 5 (gem conversion): opportunistic banking: a small bag is banked when an altar is close (altar_eta), and a 10+ bag is banked early when enemies are seen or were seen nearby recently (unseen_enemies_near).
# version 6 (gem conversion): CARRY GUARD: a carrier who sees an enemy closing (threat_eta <= 3) runs the bag to a nearby unlocked altar (dash + move) and tributes on arrival instead of fighting; per-role thresholds: Vesper guards 4+ gems, Tavi/Ryth/Ren 8+, Vendetta 8+ only when the local fight is not clearly won or the bag is 15+.
# version 8 (gem conversion): EN-ROUTE BANKING: before walking to the next camp with 6+ gems, bank when an altar is on the way (bank_detour(goal) <= 2) and no enemy is seen near that altar (enemies_near), so bags are tributed on the route instead of carried into the next fight.
# PLAN: 1) most deaths with gems happen ~7 tiles from an altar, between camps; 2) use bank_detour to find cheap banking stops on the route to the next camp;
# 3) bank a 6+ bag there when the altar is not contested (enemies_near altar 4 == 0); 4) otherwise keep v6 behaviour; no new Num slots beyond the limit.
# version 10 (team coordination): STICKY FOCUS FIRE: the team target is set only when none is alive/visible nearby (no per-champion overwrites), every champion hits the team target first when it is in reach, and a healthy non-carrier within 6 tiles walks in to join an ally already fighting it (2v1 instead of 1v1).
# TEAM PLAN: 1) one shared target per fight via set_team_target, kept until it dies or leaves view (> 8 tiles);
# 2) in reach, the team target beats "weakest in range", so both champions hit the same unit the same turn;
# 3) a healthy champion without a bag joins a fight an ally is already in (ally within 3 of the target), no solo chases;
# 4) everything else unchanged; no new Num lets (slot limit), only Unit/Bool ones.

def fight_cast(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot):
            if health() < 0.7 * max_health():
                cast_self(slot)
        elif slot_is_heal(slot):
            if health() < 0.7 * max_health():
                cast_self(slot)
        elif slot_is_aoe(slot):
            cast_at_tile(slot, unit_position(u))
        elif not slot_is_dash(slot) and not slot_is_reset(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
# one shared monolith target for the whole team (static, identical for every champion)
keep team_mono = first( monolith_tiles() )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
let foes = enemies_visible()
# remember enemy sightings every turn (used by the banking decision)
let lurk = unseen_enemies_near(10, 15)
if at_spawn:
    let lk_v = read_shared(7)
    let lk_placed = lk_v - 2 * floor( lk_v / 2 )
    let lk_bought = floor( lk_v / 2 ) - 2 * floor( lk_v / 4 )
    if lk_placed == 0 and lk_bought == 0 and not has_altar_lock():
        buy_altar_lock()
        if has_altar_lock():
            write_shared(7, lk_v + 2)
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CARRY GUARD: a carrier who sees an enemy closing runs the bag to a nearby altar and tributes instead of fighting
if not at_spawn and gems() >= 4 and exists( first(foes) ):
    let threat = threat_eta()
    let guard_role = (i_am(champ_vesper_vale()) and gems() >= 4) or (gems() >= 8 and (gems() >= 15 or not i_am(champ_vendetta()) or local_strength(6) < 1.3))
    if guard_role and threat <= 3:
        let guard_altar = first( minus( filter( altars(), within(1, position()) ), locked_altars() ) )
        if exists(guard_altar):
            tribute(guard_altar)
            end_turn()
        let guard_goal = closest( minus( altar_ring, ring(locked_altars(), 1) ) )
        if exists(guard_goal) and distance(position(), guard_goal) <= 9:
            if fuel_remaining() > 55000 and distance(position(), guard_goal) > 1:
                dash_to(0, guard_goal)
                dash_to(1, guard_goal)
            move_towards(guard_goal)
            let guard_hit = weakest( filter( foes, in_attack_range() ) )
            if exists(guard_hit) and not i_am_ranged():
                attack(guard_hit)
            end_turn()

# TEAM TARGET: shared focus, alive and visible to me
let tt = team_target()
let tt_live = exists(tt) and unit_health_frac(tt) > 0

# CAST-AHEAD: stun/damage/AoE at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        # sticky focus: only (re)name a target when the current one is gone or far away
        if not tt_live or distance(position(), unit_position(tt)) > 8:
            set_team_target(near_foe)
        let ahead_stun_first = slot_stun(0) >= slot_stun(1)
        if ahead_stun_first:
            fight_cast(0, near_foe)
            fight_cast(1, near_foe)
        else:
            fight_cast(1, near_foe)
            fight_cast(0, near_foe)

# FOCUS FIRE: the team target in reach is hit before anything else
if tt_live and not contains( spawn_region(enemy()), unit_position(tt) ):
    if (i_am_ranged() and distance(position(), unit_position(tt)) <= 3) or distance(position(), unit_position(tt)) <= 1:
        if local_strength(4) < 0.8 and unit_health_frac(tt) > 0.3473 and can_move():
            move_away_from( unit_position(tt) )
            end_turn()
        let focus_stun_first = slot_stun(0) >= slot_stun(1)
        if focus_stun_first:
            fight_cast(0, tt)
            fight_cast(1, tt)
        else:
            fight_cast(1, tt)
            fight_cast(0, tt)
        attack(tt)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
        if ability_ready(1) and slot_is_reset(1):
            cast_self(1)
        attack(tt)
        end_turn()

let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # RETREAT: outnumbered or outclassed locally and the target is not nearly dead, so step back and re-engage later
    let fight_local = local_strength(4)
    if fight_local < 0.8 and unit_health_frac(enemy) > 0.3473 and can_move():
        move_away_from( unit_position(enemy) )
        end_turn()
    # stun before burst: the slot with the stun goes first, then the other
    let stun_first = slot_stun(0) >= slot_stun(1)
    if stun_first:
        fight_cast(0, enemy)
        fight_cast(1, enemy)
    else:
        fight_cast(1, enemy)
        fight_cast(0, enemy)
    # ALLY HEAL: a hurt visible ally within heal range gets the heal slot cast on it
    let ally_low = weakest( allies_visible() )
    if exists(ally_low) and unit_health_frac(ally_low) < 0.5:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(ally_low)) <= slot_range(0):
            cast_at_unit(0, ally_low)
        if ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(ally_low)) <= slot_range(1):
            cast_at_unit(1, ally_low)
    attack(enemy)
    # attack reset: self-cast after the basic attack, then attack again
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

