if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

# MONOLITH TAKE (roles + claim_count commit)
if exists(team_mono) and round_number() > 700:
    if gems() > 0 or health() < 0.6 * max_health():
        unclaim()
    elif fuel_remaining() > 50000 and not contains( respawning_visible_spawns(), team_mono ):
        let lead_ok = (i_am(champ_vendetta()) and round_number() > 700) or round_number() > 1100
        let mono_n = claim_count(team_mono)
