# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# opener-1: open a fight with a stun or damage slot on the first-hit turn, within its full reach.
# AoE is cast at the target tile, a stun dash closes in on the target (fuel-gated), and the turn continues to the basic attack.
def open_slot(s, f):
    if ability_ready(s) and (slot_stun(s) > 0 or slot_is_damage(s)) and not slot_is_reset(s) and distance(position(), unit_position(f)) <= slot_range(s) + slot_radius(s):
        if slot_is_dash(s):
            if fuel_remaining() > 55000:
                dash_towards(s, unit_position(f))
        elif slot_radius(s) > 0:
            cast_at_tile(s, unit_position(f))
        else:
            cast_at_unit(s, f)

# pairs-1: true when unit u is my draft partner (vendetta<->vesper_vale, tavi<->ryth)
def partner_of_me(u):
    return (i_am(champ_vendetta()) and unit_is(u, champ_vesper_vale())) or (i_am(champ_vesper_vale()) and unit_is(u, champ_vendetta())) or (i_am(champ_tavi()) and unit_is(u, champ_ryth())) or (i_am(champ_ryth()) and unit_is(u, champ_tavi()))

